export const getPostUploadUrl = () => {




  return `/api/upload`
}

/**
 * @summary Upload an image
 */
export const postUpload = async (postUploadBody: PostUploadBody, options?: Parameters<typeof customFetch>[1]): Promise<Media> => {

  return customFetch<Media>(getPostUploadUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(postUploadBody)
  }
);}





export const getPostUploadMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof postUpload>>, TError,{data: BodyType<PostUploadBody>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof postUpload>>, TError,{data: BodyType<PostUploadBody>}, TContext> => {

const mutationKey = ['postUpload'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof postUpload>>, {data: BodyType<PostUploadBody>}> = (props) => {
          const {data} = props ?? {};

          return  postUpload(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type PostUploadMutationResult = NonNullable<Awaited<ReturnType<typeof postUpload>>>
    export type PostUploadMutationBody = BodyType<PostUploadBody>
    export type PostUploadMutationError = ErrorType<unknown>

    /**
 * @summary Upload an image
 */
export const usePostUpload = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof postUpload>>, TError,{data: BodyType<PostUploadBody>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof postUpload>>,
        TError,
        {data: BodyType<PostUploadBody>},
        TContext
      > => {
      return useMutation(getPostUploadMutationOptions(options));
    }

